//! `Collapse` tables written by older wirefold must stay readable.
//!
//! `tests/fixtures/legacy_collapse/` holds real output of wirefold `ba9a712` (the version sangdb pinned),
//! generated by building that version and packing the deterministic records below. That layout had no
//! version word (a table began with its bare section count) and stored all of a record's scalar fields
//! as one row-major block. Current tables begin with the `WC` magic and give each scalar field its own
//! column, so the two are told apart by the first word alone and neither reader accepts the other's
//! tables. `collapse_decode` reads both; `collapse_open` (zero-copy views) reads current tables only.
#![cfg(feature = "derive")]

use wirefold::codec::web::WireErr;
use wirefold::Collapse;

// Record and enum definitions shared by the fixture generator (built against the OLD derive) and
// tests/legacy_collapse.rs (current derive). The data is deterministic.
#[derive(Collapse, Clone, Debug, PartialEq)]
pub struct Flat {
    pub id: u64,
    pub score: f32,
    pub flag: bool,
    pub level: i16,
}

#[derive(Collapse, Clone, Debug, PartialEq)]
pub struct One {
    pub x: u32,
}

#[derive(Collapse, Clone, Debug, PartialEq)]
pub struct Child {
    pub a: u16,
    pub ok: bool,
    pub tag: String,
}

#[derive(Collapse, Clone, Debug, PartialEq)]
pub struct Parent {
    pub id: u64,
    pub label: String,
    pub kids: Vec<Child>,
    pub samples: Vec<u32>,
}

#[derive(Collapse, Clone, Debug, PartialEq)]
pub struct OnlyStrings {
    pub a: String,
    pub b: String,
}

#[derive(Collapse, Clone, Copy, Debug, PartialEq)]
pub enum Shape {
    Circle { r: f32 },
    Rect(f32, f32),
    Dot,
}

pub fn flat(n: usize) -> Vec<Flat> {
    (0..n)
        .map(|i| Flat {
            id: 1_000_000 + i as u64 * 7,
            score: i as f32 * 0.5 - 3.0,
            flag: i % 3 == 0,
            level: (i as i16) * 11 - 20,
        })
        .collect()
}
pub fn one(n: usize) -> Vec<One> {
    (0..n)
        .map(|i| One {
            x: (i as u32).wrapping_mul(2_654_435_761),
        })
        .collect()
}
pub fn parents(n: usize) -> Vec<Parent> {
    (0..n)
        .map(|i| Parent {
            id: i as u64,
            label: format!("parent-{i}"),
            kids: (0..(i % 4))
                .map(|k| Child {
                    a: (i * 10 + k) as u16,
                    ok: k % 2 == 0,
                    tag: format!("kid-{i}-{k}"),
                })
                .collect(),
            samples: (0..(i % 5) as u32).map(|v| v * 100 + i as u32).collect(),
        })
        .collect()
}
pub fn strings(n: usize) -> Vec<OnlyStrings> {
    (0..n)
        .map(|i| OnlyStrings {
            a: format!("a{i}"),
            b: "é".repeat(i),
        })
        .collect()
}
pub fn shapes() -> Vec<Shape> {
    vec![
        Shape::Circle { r: 1.5 },
        Shape::Rect(2.0, 3.5),
        Shape::Dot,
        Shape::Circle { r: -0.25 },
        Shape::Dot,
    ]
}

struct Aligned(Vec<u64>, usize);
fn aligned(b: &[u8]) -> Aligned {
    let mut w = vec![0u64; b.len().div_ceil(8).max(1)];
    // SAFETY: `w` owns at least `b.len()` bytes; u64 has no invalid bit patterns.
    unsafe { std::ptr::copy_nonoverlapping(b.as_ptr(), w.as_mut_ptr().cast::<u8>(), b.len()) };
    Aligned(w, b.len())
}
impl Aligned {
    fn bytes(&self) -> &[u8] {
        // SAFETY: the allocation is `>= self.1` bytes and 8-aligned.
        unsafe { std::slice::from_raw_parts(self.0.as_ptr().cast::<u8>(), self.1) }
    }
}
fn fixture(name: &str) -> Aligned {
    let path = format!(
        "{}/tests/fixtures/legacy_collapse/{name}.bin",
        env!("CARGO_MANIFEST_DIR")
    );
    aligned(&std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}")))
}

#[test]
fn old_record_tables_decode_to_the_records_that_were_packed() {
    assert_eq!(
        Flat::collapse_decode(fixture("flat_5").bytes()).unwrap(),
        flat(5)
    );
    assert_eq!(
        Flat::collapse_decode(fixture("flat_0").bytes()).unwrap(),
        flat(0)
    );
    assert_eq!(
        One::collapse_decode(fixture("one_4").bytes()).unwrap(),
        one(4)
    );
    assert_eq!(
        OnlyStrings::collapse_decode(fixture("strings_3").bytes()).unwrap(),
        strings(3)
    );
}

/// A record with strings, a nested table of records and a `Vec<u32>` column: every layer of the old layout.
#[test]
fn an_old_nested_table_decodes() {
    assert_eq!(
        Parent::collapse_decode(fixture("parents_6").bytes()).unwrap(),
        parents(6)
    );
}

#[test]
fn an_old_enum_table_decodes() {
    assert_eq!(
        Shape::collapse_decode(fixture("shapes_5").bytes()).unwrap(),
        shapes()
    );
}

/// The readers are told apart by the table word, and neither accepts the other's tables.
#[test]
fn the_current_and_legacy_readers_never_accept_each_others_tables() {
    let old = fixture("flat_5");
    assert_eq!(
        FlatView::collapse_open(old.bytes()).err(),
        Some(WireErr::BadMagic),
        "a view refuses an old table"
    );
    let current = aligned(Flat::collapse_encode(&flat(5)).as_bytes());
    assert_eq!(
        Flat::collapse_decode(current.bytes()).unwrap(),
        flat(5),
        "a current table decodes"
    );
    assert_eq!(
        Flat::collapse_decode_legacy(current.bytes()).unwrap_err(),
        WireErr::BadMagic
    );
    let old_enum = fixture("shapes_5");
    assert_eq!(
        Shape::collapse_decode_legacy(old_enum.bytes()).unwrap(),
        shapes()
    );
    let current_enum = aligned(Shape::collapse_encode(&shapes()).as_bytes());
    assert_eq!(
        Shape::collapse_decode_legacy(current_enum.bytes()).unwrap_err(),
        WireErr::BadMagic
    );
    // a one-scalar record: the old block and the current column hold the same bytes, only the word differs
    let one_old = fixture("one_4");
    assert_eq!(One::collapse_decode(one_old.bytes()).unwrap(), one(4));
}

/// What is written now is the current layout (a legacy table is never produced), and it round-trips.
#[test]
fn writing_always_produces_the_current_layout() {
    for items in [flat(0), flat(1), flat(9)] {
        let seed = Flat::collapse_encode(&items);
        let word = u64::from_le_bytes(seed.as_bytes()[..8].try_into().unwrap());
        assert_eq!(
            (word >> 32) as u32,
            u32::from_le_bytes([b'W', b'C', 1, 0]),
            "the magic is written"
        );
        assert_eq!(
            Flat::collapse_decode(aligned(seed.as_bytes()).bytes()).unwrap(),
            items
        );
    }
    let parents6 = Parent::collapse_encode(&parents(6));
    assert_eq!(
        Parent::collapse_decode(aligned(parents6.as_bytes()).bytes()).unwrap(),
        parents(6)
    );
}

/// A damaged or cut old table is an error, never a panic and never other data.
#[test]
fn damaged_and_truncated_old_tables_are_refused_without_panics() {
    type Decode = fn(&[u8]) -> Result<usize, WireErr>;
    let cases: [(&str, Decode); 5] = [
        ("flat_5", |b| Flat::collapse_decode(b).map(|v| v.len())),
        ("one_4", |b| One::collapse_decode(b).map(|v| v.len())),
        ("parents_6", |b| Parent::collapse_decode(b).map(|v| v.len())),
        ("strings_3", |b| {
            OnlyStrings::collapse_decode(b).map(|v| v.len())
        }),
        ("shapes_5", |b| Shape::collapse_decode(b).map(|v| v.len())),
    ];
    for (name, decode) in cases {
        let good = fixture(name);
        let want = decode(good.bytes()).unwrap();
        for cut in 0..good.bytes().len() {
            if let Ok(n) = decode(aligned(&good.bytes()[..cut]).bytes()) {
                // a cut that leaves a complete shorter table is the only way to succeed
                assert!(n <= want, "{name} cut at {cut} decoded {n} records");
            }
        }
        for at in 0..good.bytes().len() {
            for flip in [0x01u8, 0x80, 0xFF] {
                let mut bad = good.bytes().to_vec();
                bad[at] ^= flip;
                let _ = decode(aligned(&bad).bytes()); // must not panic
            }
        }
    }
    // a record count that the buffer cannot back, in a table with no scalar columns
    let mut huge = fixture("strings_3").bytes().to_vec();
    huge[8..16].copy_from_slice(&u64::MAX.to_le_bytes());
    assert!(OnlyStrings::collapse_decode(aligned(&huge).bytes()).is_err());
}

#[test]
fn foreign_buffers_are_refused() {
    for junk in [
        vec![],
        vec![1u8; 7],
        vec![0u8; 8],
        vec![0xFFu8; 64],
        b"not a table at all, just text.".to_vec(),
    ] {
        assert!(Flat::collapse_decode(aligned(&junk).bytes()).is_err());
        assert!(Shape::collapse_decode(aligned(&junk).bytes()).is_err());
    }
}
